const arr = [1, 2, 2, 3, 4, 4, 5];
const unique = [...new Set(arr)];
const filtered = arr.filter((v, i) => arr.indexOf(v) === i);
console.log(JSON.stringify(filtered) === JSON.stringify(unique));
